function taleWeek(){const w=wk();if(!S.bkW||S.bkW.w!==w){const own=taleOwn(),pool=TALES.filter(t=>t.src==='shop');let x=w*2654435761>>>0;const r=()=>{x=(x*1664525+1013904223)>>>0;return x/4294967296};const sh=pool.map(t=>[own[t.k]?1:0,r(),t.k]).sort((a,b)=>a[0]-b[0]||a[1]-b[1]);S.bkW={w,list:sh.slice(0,3).map(z=>z[2])}}return S.bkW.list}
