/* ---------- tree room bounds (v0.99v): furniture stays on the floor, wall decor stays on the wall ---------- */
const TREE_FLOOR=[[172,380],[758,380],[895,450],[925,560],[915,660],[880,750],[800,815],[700,860],[560,882],[420,880],[300,850],[225,795],[160,715],[112,610],[128,470]],TREE_WALLDEC={d_lamp:1,d_wlamp:1,d_vine:1,d_pic1:1,d_pic2:1};
function ptIn(P,x,y){let c=false;for(let i=0,j=P.length-1;i<P.length;j=i++){const a=P[i],b=P[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])c=!c}return c}
function treeVis(){try{const M=room&&room.map,st=$('stage');if(!M||!st||!st.clientWidth)return null;const u=PXS*M.k;return[(-M.ox)/u+3,(st.clientWidth-M.ox)/u-3]}catch(e){return null}}
function treeOK(k,p,H){const G=treeGeo(H),z=TREE_SZ[k];if(!z||!p)return true;const ix=u=>(u-G.SX)/G.k1,iy=v=>(v-G.top)/G.k1,x0=ix(p[0]),x1=ix(p[0]+z[0]),yt=iy(p[1]),yb=iy(p[1]+z[1]);
  {const V=treeVis();if(V&&(p[0]<V[0]||p[0]+z[0]>V[1]))return false}if(TREE_WALLDEC[k])return x0>=125&&x1<=900&&yt>=30&&yb<=385;const m=Math.min(14,(x1-x0)*.15);return ptIn(TREE_FLOOR,x0+m,yb)&&ptIn(TREE_FLOOR,x1-m,yb)}
function treeMove(k,a,b,H){if(treeOK(k,b,H))return b;if(!treeOK(k,a,H))a=treeFix(k,a,H);let best=a;for(let t=.05;t<=1.0001;t+=.05){const q=[Math.round(a[0]+(b[0]-a[0])*t),Math.round(a[1]+(b[1]-a[1])*t)];if(treeOK(k,q,H))best=q}return best}
function treeCtr(k,H){const G=treeGeo(H),z=TREE_SZ[k],W=TREE_WALLDEC[k];return[Math.round(G.bx(520)-z[0]/2),Math.round(G.by(W?330:640)-z[1])]}
function treeFix(k,p,H){if(!p||treeOK(k,p,H))return p;const c=treeCtr(k,H);for(let t=.05;t<=1.0001;t+=.05){const q=[Math.round(p[0]+(c[0]-p[0])*t),Math.round(p[1]+(c[1]-p[1])*t)];if(treeOK(k,q,H))return q}return c}

