const MAIL_FIX=[{id:'upd-1.00z',ic:'📚',d:'2026-10-23',t:TL("อัปเดต: ร้านหนังสือ และอีกหลายอย่าง"),b:[['🏛️',TL("หอผู้พิทักษ์: ประตูมิติในฟาร์มพาไปห้องโถงของผู้พิทักษ์ที่ช่วยออกมา · ขอพรได้วันละครั้ง สุ่มค่าพลัง +1% ต่อผู้พิทักษ์ (สูงสุด 10%) ทั้งวัน")],['📚',TL("ร้านหนังสือเปิดแล้ว (แทนห้องสมุด): นิทานสั้นหมุนเวียนทุกสัปดาห์ และโปสเตอร์น้องๆ ติดผนังบ้าน")],['📕',TL("หน้ากระดาษนิทานบางเล่มหล่นอยู่ในหอคอย · อ่านทุกเล่มได้ที่ชั้นหนังสือ → สมุดเรื่องราว")],['🎁',TL("บอร์ดปฏิทิน: ปุ่มรับทั้งหมดทุกหัวข้อ (รวมของขวัญจากน้องหมี) + จุดแดงบอกแท็บที่ยังไม่รับ")],['🌾',TL("ฟาร์ม: มีรางอาหารให้เห็นแล้ว น้องหิวจะเดินไปกิน · เปิด 🎒 กระเป๋าแล้วลากอาหารไปป้อนน้องหรือใส่รางได้เลย")],['🔥',TL("แตะ Kcal ด้านบนเพื่อดูสถิติและข้อมูลสุขภาพ · ชั้นหนังสือมีสมุดสะสมและสมุดเรื่องราว")],['🎨',TL("ปรับโทนสีเมืองและฟาร์มให้อบอุ่นเข้ากับบ้าน · เตียงเปลี่ยนชื่อเป็น พักผ่อน · เครื่องฟักไข่ชื่อเดียวทั้งเกม")]]},{id:'story-1',ic:'📖',d:'2026-10-23',t:TL("เรื่องราวใหม่: บทนำแห่งลูโทเนีย"),b:[['🌫️',TL("บทนำเล่าใหม่ทั้งหมด: หมอกพิษแห่งเดดการ์ หอคอยดำทมิฬ และผู้พิทักษ์ที่ถูกขังไว้")],['🗼',TL("คัตซีนจบเฟส 3 ภูเขาไฟ และเฟส 4 ทะเลสาบน้ำแข็ง")],['⭐',TL("ดาวเศษเปลี่ยนชื่อเป็น จิตวิญญาณแห่งป่า · เมืองของเราชื่อ ไลท์ทาวน์")],['📖',TL("ดูบทนำใหม่ได้ที่ชั้นหนังสือในบ้าน → สมุดเรื่องราว")]]},{id:'upd-1.00',ic:'📢',d:'2026-10-23',t:TL("อัปเดต 1.00 · มีอะไรใหม่"),b:[["🗼",TL("หน้าหอคอยใหม่: ชั้นที่ผ่านแล้วไฟติดแดง · ป้ายบอกด่านถัดไป · สำรวจด่านต่อได้ทันที")],["🧭",TL("ส่งน้องสำรวจ 8 ชั่วโมง เก็บคริสตัล เศษวัสดุ และวัตถุดิบ (ปลดล็อกเมื่อชนะบอสชั้นแรก)")],["🎒",TL("ของจากด่านเข้ากระเป๋า · กระเป๋าเต็มเลือกเองว่าจะเก็บอะไร")],["🍎",TL("ร้านผลไม้: ผลไม้ค่าพลังเหลือลูกละ 40 · สตรอว์เบอร์รีเพิ่มทีละ 3 ค่า")],["🍱",TL("ร้านอาหารมีเมนูสำเร็จรูป (ทำเองยังได้ EXP มากกว่า)")],["🪴",TL("ร้านของตกแต่ง: กาชาของตกแต่ง · สีของ · ธีมห้อง · จัดได้ที่ ☰ → จัดห้อง")],["🔤",TL("ตัวอักษรใหญ่ขึ้นทั้งเกม · ลากนิ้วผ่านของเพื่อดูชื่อ")],["🧸",TL("น้องหมีส่งจดหมาย: ข่าวอัปเดต อีเวนต์ และของขวัญ · เห็น ✉️ บนหัวน้องหมีเมื่อไหร่ แตะได้เลย")]],gift:{cry:30},gn:TL("ขอบคุณที่เลี้ยงน้องกับเรา 💜")}];

function mailBox(){S.mail=S.mail||{list:[]};return S.mail}
function mailAdd(m){const B=mailBox();if(B.list.some(x=>x.id===m.id)||(B.gone||[]).includes(m.id))return false;B.list.unshift(Object.assign({ts:Date.now(),read:0,got:0},m));return true}
function mailUnread(){if(!S)return 0;return mailBox().list.filter(m=>!m.read||(!m.got&&mailView(m).gift)).length}
function mailTick(){if(!S)return;let ch=false;MAIL_FIX.forEach(m=>{if(mailAdd({id:m.id,fix:1}))ch=true});
  const a=evActive();if(a){const id=a.id;if(mailAdd({id:'ev-'+id,ic:'🎃',ev:a.k,kind:'start'}))ch=true;if(evDaysLeft()<=3&&mailAdd({id:'evend-'+id,ic:'⏰',ev:a.k,kind:'end'}))ch=true}
  const E=S.expd||{};for(const ph in E){const e=E[ph];if(Date.now()-e.t0>=EX_MS){const p=S.pets.find(x=>x.id===e.id);if(mailAdd({id:'ex-'+ph+'-'+e.t0,ic:'🧭',kind:'ex',pn:p?p.name:'',ph:+ph}))ch=true}}
  const B=mailBox(),cut=Date.now()-30*86400000,keep=[];B.gone=B.gone||[];B.list.forEach(m=>{if(m.ts<cut&&m.read&&(!m.gift||m.got)&&!m.fix){B.gone.push(m.id)}else keep.push(m)});B.list=keep;B.gone=B.gone.slice(-80);
  if(ch){save();try{houseRefresh()}catch(e){}}}
function mailView(m){const F=m.fix&&MAIL_FIX.find(x=>x.id===m.id);if(F)return{ic:F.ic,t:F.t,d:F.d,body:'<ul style="margin:0;padding-left:4px;list-style:none;line-height:1.7">'+F.b.map(([i,t])=>'<li>'+pxi(i,16)+' '+t+'</li>').join('')+'</ul>'+(F.gn?'<p style="margin:8px 0 0">'+F.gn+'</p>':''),gift:F.gift};
  if(m.kind==='start'||m.kind==='end'){const E=EVENTS[m.ev]||{},to=E.to||[1,1],from=E.from||[1,1],dt=x=>x[1]+' '+TL(['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][x[0]-1]);
    return m.kind==='start'?{ic:'🎃',t:TL('อีเวนต์เริ่มแล้ว: ')+TL(E.n||''),body:'<p style="margin:0">'+TL('ช่วงอีเวนต์ ')+dt(from)+' – '+dt(to)+'</p><p style="margin:6px 0 0">'+TL('ออกกำลังกายช่วงนี้ สะสม Kcal ปลดล็อกชุดอีเวนต์ฟรี · ดูความคืบหน้าที่ปฏิทินบนผนัง · ชุดอีเวนต์สุ่มได้ที่กาชาชุดด้วย')+'</p>'}
      :{ic:'⏰',t:TL('อีเวนต์ใกล้จบ: ')+TL(E.n||''),body:'<p style="margin:0">'+TL('เหลืออีกไม่เกิน 3 วัน (จบ ')+dt(to)+')</p><p style="margin:6px 0 0">'+TL('ยังเก็บชุดไม่ครบ? ออกกำลังกายอีกนิดก่อนอีเวนต์จบนะ')+'</p>'}}
  if(m.kind==='ex')return{ic:'🧭',t:(m.pn?m.pn+' ':'')+TL('กลับจากสำรวจแล้ว'),body:'<p style="margin:0">'+TL('กด 🧭 ในหน้าเลือกด่านเพื่อรับรางวัล')+'</p>'};
  return{ic:'✉️',t:'',body:''}}
function mailSheet(){mailTick();let open=null;openSheet('<h2>🧸 '+TL('น้องหมีส่งจดหมาย')+'</h2><div id="mlB"></div>',(b,ov)=>{const draw=()=>{const L=mailBox().list;
    let h=L.length?'<div style="display:flex;flex-direction:column;gap:6px">'+L.map(m=>{const v=mailView(m),on=open===m.id,dd=new Date(m.ts);return'<div class="card" style="margin:0;padding:8px 10px"><button data-ml="'+m.id+'" style="all:unset;display:flex;gap:10px;align-items:center;width:100%;cursor:pointer"><span style="font-size:22px">'+pxi(v.ic,24)+'</span><span style="flex:1;min-width:0"><b style="'+(m.read?'opacity:.7;font-weight:500':'')+'">'+v.t+'</b><br><small class="mut num">'+dd.getDate()+'/'+(dd.getMonth()+1)+'</small></span>'+(!m.read?'<i style="width:9px;height:9px;border-radius:50%;background:#ff5a5a;flex:0 0 auto"></i>':'')+(v.gift&&!m.got?'<span class="tag">🎁</span>':'')+'</button>'+
      (on?'<div style="margin-top:8px;font-size:14px">'+v.body+(v.gift?(m.got?'<p class="mut" style="margin:8px 0 0">✓ '+TL('รับของขวัญแล้ว')+'</p>':'<button class="btn kcal" data-mg="'+m.id+'" style="width:100%;margin-top:8px">🎁 '+TL('รับของขวัญ')+' · 💎 '+v.gift.cry+'</button>'):'')+'</div>':'')+'</div>'}).join('')+'</div>':'<p class="mut" style="text-align:center">'+TL('ยังไม่มีจดหมาย')+'</p>';
    if(L.some(m=>!m.read))h+='<button class="btn" id="mlAll" style="width:100%;margin-top:8px">'+TL('อ่านทั้งหมด')+'</button>';
    b.querySelector('#mlB').innerHTML=h;
    b.querySelectorAll('[data-ml]').forEach(x=>x.onclick=()=>{const m=mailBox().list.find(z=>z.id===x.dataset.ml);if(!m)return;open=open===m.id?null:m.id;if(!m.read){m.read=1;save();houseRefresh()}SND.play('tap');draw()});
    b.querySelectorAll('[data-mg]').forEach(x=>x.onclick=()=>{const m=mailBox().list.find(z=>z.id===x.dataset.mg),v=m&&mailView(m);if(!m||m.got||!v.gift)return;m.got=1;m.read=1;S.cry=(S.cry||0)+(v.gift.cry||0);save();renderTop();houseRefresh();SND.play('legend');toast('💎 +'+v.gift.cry);draw()});
    const al=b.querySelector('#mlAll');if(al)al.onclick=()=>{mailBox().list.forEach(m=>m.read=1);save();houseRefresh();SND.play('tap');draw()}};draw()})}
setInterval(()=>{try{mailTick()}catch(e){}},60000);
function houseRefresh(){roomNight();{const m=document.querySelector('.hobj[data-h=teddy] .tdm');if(m)m.hidden=!(S&&mailUnread()>0)}try{renderTeamBar()}catch(e){}document.querySelectorAll('.hobj,.hgl').forEach(b=>{const k=b.dataset.h;b.classList.toggle('hot',houseHot(k));if(b.classList.contains('hgl'))return;})}
function advCheck(){if(S&&!teamPets().length){const rd=S.pets.filter(p=>!p.egg&&!p.coc&&!onEx(p));if(rd.length){S.team=[(rd.find(p=>p.id===S.main)||rd[0]).id];save()}else if(hatchedPets().length){toast(TL('น้องทุกตัวอยู่ในดักแด้ ออกจากดักแด้ก่อนนะ'));cocoonSheet(hatchedPets()[0].id);return false}}if(S&&!hatchedPets().length){{const fe=incEgg();if(fe&&fe.first){toast(TL('บันทึกออกกำลังกายครั้งแรก ไข่จะฟัก แล้วค่อยออกผจญภัยนะ'));exerciseSheet();return false}}toast(TL('ฟักไข่ใบแรกก่อนนะ แล้วค่อยออกผจญภัย'));gachaSheet();return false}return true}

